import Image from "next/image";
import { cn } from "@/lib/utils";

/**
 * The CLUB JOIA 300 logo, rendered from the official artwork in /public/brand
 * (CJ300_Logo_wht / _wht_rd / _blk / _clr.png). public/brand/web holds trimmed copies generated by
 * `npm run brand:logos` — never redraw the logo in CSS.
 */
export type LogoVariant = "white" | "white-red" | "black" | "color";

const LOGOS: Record<LogoVariant, { src: string; ratio: number }> = {
  white: { src: "/brand/web/CJ300_Logo_wht.png", ratio: 199 / 800 },
  "white-red": { src: "/brand/web/CJ300_Logo_wht_rd.png", ratio: 200 / 800 },
  black: { src: "/brand/web/CJ300_Logo_blk.png", ratio: 205 / 800 },
  color: { src: "/brand/web/CJ300_Logo_clr.png", ratio: 201 / 800 },
};

export function JoiaLogo({
  variant = "color",
  width = 132,
  className,
  priority,
}: {
  variant?: LogoVariant;
  width?: number;
  className?: string;
  priority?: boolean;
}) {
  const logo = LOGOS[variant];
  return (
    <Image
      src={logo.src}
      alt="CLUB JOIA 300"
      width={width}
      height={Math.round(width * logo.ratio)}
      className={cn("h-auto select-none", className)}
      // Logos sit above the fold everywhere; `priority` (deprecated in Next 16) maps to a high fetch priority.
      loading="eager"
      fetchPriority={priority ? "high" : undefined}
      unoptimized
      draggable={false}
    />
  );
}
